import * as React from "react"

function AnimatedInfoCard({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="animated-info-card"
      className={className}
      {...props}
    >
      <div className="size-52">
        <svg id="animated" viewbox="0 0 100 100">
          <circle cx="50" cy="50" r="45" fill="#FDB900" />
          <path fill="none" strokeLinecap="round" strokeWidth="5" stroke="#fff" stroke-dasharray="251.2,0"
            d="M50 10 a 40 40 0 0 1 0 80 a 40 40 0 0 1 0 -80">
            <animate attributeName="stroke-dasharray" from="0,251.2" to="251.2,0" dur="5s" />
          </path>
          <text id="count" className="stroke-white fill-white" x="50" y="35" text-anchor="middle" dy="7"
            font-size="10">VIEWS</text>
          <text id="count" className="stroke-white fill-white" x="50" y="55" text-anchor="middle" dy="7"
            font-size="20">15k</text>
        </svg>
      </div>
    </div>
  )
}

export { AnimatedInfoCard }
